(function(root){'use strict';
const A=root.CoachAcademy,C=root.CoachCore,E=root.ExamCoach,esc=C.escapeHTML;
let api,main,activeRepair=null,projectStep=0,projectQ='',reviewDrafts={};
const h=s=>esc(s),link=(route,text,cls='secondary')=>`<a class="button ${cls}" href="#${route}">${h(text)}</a>`;
const btn=(action,text,attrs='',cls='secondary')=>`<button type="button" class="button ${cls}" data-academy="${action}" ${attrs}>${h(text)}</button>`;
const field=(name,label,value='',type='textarea',attrs='')=>`<label class="field"><span class="field-label">${h(label)}</span>${type==='textarea'?`<textarea data-ac-field="${h(name)}" ${attrs}>${h(value)}</textarea>`:`<input data-ac-field="${h(name)}" type="${type}" value="${h(value)}" ${attrs}>`}</label>`;
const value=name=>main.querySelector(`[data-ac-field="${name}"]`)?.value||'';
const get=()=>api.state(),data=()=>api.data(),state=()=>{get().academy||=A.empty();return get().academy;};
const commit=()=>api.save();
const qby=id=>data().questions.find(q=>q.id===id);
const eligible=()=>data().questions.filter(q=>A.ready(q,data().passages));
const title=q=>`${q.year} · ${data().passages.find(p=>p.id===q.passages[0])?.title||''} · 第${q.number}題`;
function header(name,desc){return `<div class="page-head"><div><div class="eyebrow">DSE · 閱讀理解</div><h1>${h(name)}</h1><p>${h(desc)}</p></div></div>`;}
function shell(content){main.innerHTML=content+'<p id="academy-status" role="status" aria-live="polite"></p>';}
function status(text,error=false){const el=document.getElementById('academy-status');if(el){el.textContent=text;el.className=error?'note':'note neutral';el.scrollIntoView?.({block:'nearest'});}else api.toast(text);}
function sources(q){return `<details class="source-list"><summary>來源與核對版本</summary><p>核對日期：${h(q.provenance.checkedAt)} · ${h(q.provenance.version)}。頁碼為PDF頁序。</p><ul>${Object.entries(q.source).map(([kind,s])=>`<li><a target="_blank" rel="noopener" ${kind==='answer'?'data-source-exposure="'+h(q.id)+'"':''} href="${h(s.url)}">${h(s.name)}</a> · 第${h(s.pages)}頁</li>`).join('')}</ul></details>`;}
function passage(q,select=false,chosen=[]){return q.passages.map(id=>{const p=data().passages.find(p=>p.id===id);return `<article class="ac-passage"><h2>${h(p.title)}</h2><p class="field-help">${h(p.label)}</p>${p.paragraphs.map((t,i)=>`<p class="paragraph"><span class="paragraph-number">${i+1}</span>${select?(data().compiled.passages.find(p=>p.id===id).paragraphs[i].sentences.map(s=>`<button type="button" class="sentence ${chosen.includes(s.id)?'selected':''}" aria-pressed="${chosen.includes(s.id)}" data-academy="repair-evidence" data-id="${h(s.id)}">${h(s.text)}</button>`).join('')):h(t)}</p>`).join('')}</article>`;}).join('');}
function questionCards(qs){return `<div class="ac-grid">${qs.map(q=>`<article class="surface"><span class="tag">${h(q.year)} DSE · 原題${q.marks}分</span><h2>${h(title(q))}</h2><p>${h(q.prompt)}</p><p class="field-help">${h(A.exposure(q.id,get().drafts,state().declarations).label)}</p><div class="button-row">${link('practice/'+q.id,'自主試答')}${link('project/'+q.id,'課堂講解','quiet')}</div>${sources(q)}</article>`).join('')}</div>`;}
function home(){const qs=eligible(),done=qs.filter(q=>get().drafts[q.id]?.completedAt).length;const next=qs.filter(q=>get().drafts[q.id]&&!get().drafts[q.id].completedAt).sort((a,b)=>(get().drafts[b.id].updatedAt||'').localeCompare(get().drafts[a.id].updatedAt||''))[0]||qs[0];shell(`<section class="hero"><div><div class="eyebrow">READ · THINK · EXPLAIN</div><h1>從真題出發，<br>把理由說清楚。</h1><p>先獨立作答，再找證據、補推論。用另一篇DSE文章，檢視方法能否再用一次。</p><div class="button-row">${link('practice/'+next.id,'繼續真題練習 →','primary')}${link('repairs','修補失分答案')}</div></div><aside class="hero-card"><span>已完成作答及自檢</span><strong>${done}<span> / ${qs.length}題</span></strong><p>只收正式DSE白話文真題<br>書面答案由教師覆核</p></aside></section><div class="ac-grid ac-entry"><article class="surface"><h2>2024《繁盛》</h2><p>15段原文 · 第9–20題 · 原滿分35分</p>${link('exercise/dse2024-fansheng','整份練習與逐題精講')}</article><article class="surface"><h2>修補 → 遷移</h2><p>9項來源舉隅修補 · 6道跨年真題</p>${link('challenge','跨年自主挑戰')}</article><article class="surface"><h2>課堂收發</h2><p>作業包 → 交卷包 → 教師回饋 → 重交</p>${link('classroom','進入課堂')}</article></div><div class="section-heading"><h2>其他年份 · 已核對真題</h2><p>目前選錄部分白話題目，不代表全卷。</p></div>${questionCards(qs.filter(q=>q.year!==2024))}<p class="note neutral">舊原創練習只保留在歷史記錄及完整備份，不再用於新練習、派題或能力判斷。${link('records','查看歷史記錄','quiet')}</p>`);}
function challenge(){const a=state();shell(header('跨年份自主挑戰','保留完整篇章及原分題。先保存首答，才由你決定是否取用支援。')+`<p class="note neutral">「未有接觸紀錄」只代表本機記錄；如你曾在課堂或其他地方做過，請申報。配對方法在教師題庫查看，避免自主試答前透露方向。</p>${questionCards(eligible().filter(q=>q.year!==2024))}<section class="surface"><h2>我的接觸紀錄</h2>${eligible().map(q=>`<label class="choice"><input type="checkbox" data-ac-declare="${h(q.id)}" ${a.declarations[q.id]?'checked':''}><span>${h(title(q))}：我曾做過／看過答案</span></label>`).join('')}</section>`);}
function repairList(){const a=state();shell(header('失分答案修補站','一次處理一個缺口。先診斷、選證據、重寫，再開啟修訂指引。')+`<p class="note neutral">以下答案與原有分數來自2024評卷舉隅。診斷及修訂指引為教練整理；你的重寫仍須教師覆核。</p><div class="ac-grid">${A.repairs(api.coaching).map(r=>`<article class="surface"><span class="tag">2024 第${qby(r.qid).number}題 · 約2–4分鐘</span><h2>${h(r.title)}</h2><p>${a.repairs[r.id]?.savedAt?'已保存重寫 · 待教師覆核':'尚未保存重寫'}</p>${link('repair/'+r.id,'進入修補 →')}</article>`).join('')}</div>`);}
function repair(id){const a=state(),r=A.repairs(api.coaching).find(r=>r.id===id);if(!r)return repairList();activeRepair=id;const q=qby(r.qid),d=a.repairs[id]||={diagnosis:'',rewrite:'',evidence:[]};api.noteExposure(q.id,'examples');shell(header('第'+q.number+'題 · 答案修補','這是原題的學習步驟，不另設考試分數。')+`<div class="button-row">${link('repairs','← 全部修補')}${link('practice/'+q.id,'返回原題')}</div><div class="ac-two"><section class="surface">${E.promptHTML(q)}<h2>來源失分舉隅</h2><blockquote class="answer-text">${h(r.case.text)}</blockquote><p class="field-help">${h(r.case.source.name)} · 第${h(r.case.source.pages)}頁。先診斷，再查看原分數及指引。</p><details><summary>打開原文，點選證據</summary>${passage(q,true,d.evidence)}</details><p id="repair-selected">已選 ${d.evidence.length} 句證據</p></section><section class="surface">${field('diagnosis','1. 這個答案最需要修補甚麼？請說明理由。',d.diagnosis,'textarea','maxlength="3000"')}${field('rewrite','2. 根據原題補寫或重寫關鍵分析。',d.rewrite,'textarea','maxlength="12000"')}<div class="button-row">${btn('save-repair','保存診斷與重寫','','primary')}${btn('reveal-repair','查看來源例答與指引',d.savedAt?'':'disabled')}</div><p class="save-label">草稿保存在此瀏覽器</p>${d.first?`<details><summary>首答與${d.versions.length}個保存版本</summary><p>首答診斷：${h(d.first.diagnosis)}</p><p class="answer-text">${h(d.first.rewrite)}</p>${d.versions.map((v,i)=>`<details><summary>版本${i+1} · ${h(v.at)}</summary><p class="answer-text">${h(v.rewrite)}</p></details>`).join('')}</details>`:''}${d.revealedAt?`<section class="note neutral"><h2>來源分數：${r.case.score} / ${r.case.outOf}</h2><p>${h(r.case.diagnosis)}</p><h3>修訂指引（教練整理）</h3><ol>${r.case.repair.map(s=>`<li>${h(s)}</li>`).join('')}</ol><p>揭示時間：${h(d.revealedAt)}。診斷正確或有重寫不代表已掌握。</p></section>${E.markingHTML(q,{}, {reveal:true})}${transfer(q)}`:''}</section></div>`);}
function transfer(q){const pairs=A.candidates(q,data().questions,data().passages,get().drafts,state().declarations);return `<section class="transfer-practice"><h3>下一步：其他年份真題</h3><p>同題重寫及跨篇自主表現會分開記錄。</p>${pairs.map(p=>`${link('practice/'+p.to,title(p.q))}<p class="field-help">${h(A.exposure(p.to,get().drafts,state().declarations).label)}</p>`).join('')||link('challenge','查看跨年真題')}</section>`;}
function abilities(){const a=state();shell(header('能力與重練路線','按具體答案及教師覆核顯示證據；不換算DSE等級。')+`<label class="field"><span>查看哪一份學習記錄</span><select data-ac-field="ability-code"><option value="">本機自主練習</option>${[...new Set(Object.values(a.submissions).map(s=>s.studentCode))].map(code=>`<option value="${h(code)}" ${a.abilityStudentCode===code?'selected':''}>課堂學生 ${h(code)}</option>`).join('')}</select></label><div class="ac-grid">${['effect','theme','emotion'].map(s=>{const x=A.ability(s,data().questions,data().passages,get().drafts,a);const due=(a.abilityStudentCode?[]:x.questions).filter(q=>get().drafts[q.id]?.completedAt).flatMap(q=>A.dueDates(get().drafts[q.id].completedAt,a.reviewDays).map(d=>({...d,q})));const pending=(a.abilityStudentCode?[]:x.questions).find(q=>get().drafts[q.id]?.teacherReview?.items?.some(i=>['revise','discuss'].includes(i.status)));return `<article class="surface"><h2>${h(C.TASK_PRINCIPLES.find(p=>p.id===s).text)}</h2><p class="note neutral">${h(x.label)}</p><p>自檢、字數、看解說及同題重答，不會產生跨文本覆核證據。</p>${pending?`<p>優先修訂：教師已指出缺口。</p>${link('practice/'+pending.id,title(pending))}`:''}<details><summary>判斷依據（${x.evidence.length}份答案）</summary>${x.evidence.map(e=>`<article><h3>${h(title(qby(e.qid)))}</h3><p>${h(e.source)} · ${h(e.at)} · ${e.current?'目前答案':'舊答案版本'}</p><p class="answer-text">${h(e.answer)}</p></article>`).join('')||'<p>尚未有足夠教師覆核。</p>'}</details>${due.length?`<h3>站內重練建議（香港日期）</h3>${due.map(d=>`<p>${h(d.date)} · 完成後第${d.days}天 ${d.date<=A.hkDate(A.now())?'· 已到建議日期':''}<br>${link('practice/'+d.q.id,title(d.q),'quiet')}</p>`).join('')}`:''}<div class="button-row">${link('repairs','修補缺口')}${link('challenge','另一篇自主挑戰')}</div></article>`;}).join('')}</div><section class="surface"><h2>重練間隔</h2>${field('day1','第一次重練：完成後幾天',a.reviewDays[0],'number','min="1" max="365"')}${field('day2','第二次重練：完成後幾天',a.reviewDays[1],'number','min="1" max="365"')}${btn('save-days','保存間隔')}</section>`);}
function project(id){const q=qby(id);if(!q||!A.ready(q,data().passages))return home();if(projectQ!==id){projectQ=id;projectStep=0;}const lesson=api.coaching.lessons[id],steps=lesson?.steps||q.evidenceAnalysis.map(e=>({title:'第'+e.paragraph+'段',evidence:[e],read:e.quote,infer:e.why}));const slides=[{label:'原題',body:E.promptHTML(q)},...steps.map(s=>({label:s.title,body:`${s.evidence.map(e=>`<blockquote>第${e.paragraph}段：${h(e.quote)}</blockquote>`).join('')}<p>${h(s.read)}</p><p><strong>推論：</strong>${h(s.infer)}</p>`})),{label:'落筆及核對',body:`<ul>${q.rubric.map(r=>`<li>${h(r.label)}：${h(r.detail)}</li>`).join('')}</ul><p>以上為教練整理，自檢欄不逐項給分。</p>`}];if(lesson?.mistakes?.length){const m=lesson.mistakes[0];slides.push({label:'來源答案：先找問題',body:`<blockquote>${h(m.text)}</blockquote><p class="field-help">${h(m.source.name)} · 第${h(m.source.pages)}頁</p>`},{label:'來源答案：修訂方向',body:`<p>來源分數 ${m.score}/${m.outOf}</p><p>${h(m.diagnosis)}</p><ol>${m.repair.map(s=>`<li>${h(s)}</li>`).join('')}</ol>`});}projectStep=Math.max(0,Math.min(projectStep,slides.length-1));shell(`<section class="projection">${link('teacher','結束投影','quiet')}<p>${h(title(q))} · 教師講解 · ${projectStep+1}/${slides.length}</p><h1>${h(slides[projectStep].label)}</h1><div class="projection-focus">${slides[projectStep].body}</div><div class="button-row">${btn('project-prev','← 上一步',projectStep?'':'disabled')}${btn('project-next','下一步 →',projectStep===slides.length-1?'disabled':'','primary')}</div><p class="field-help">方向鍵左右切換。投影不改學生作答、支援或能力記錄。</p></section>`);}
function teacher(){const a=state();shell(header('真題與教學指引管理','原文、原題及來源評分與教練講解分開保存。')+`<div class="toolbar">${btn('export-true-bank','匯出已核對真題包')}${btn('import-true-bank','匯入真題包')}<input id="true-bank-file" type="file" accept=".json" hidden>${link('classroom','課堂派題與覆核')}</div><p class="note neutral">匯入後先列待核對。程式檢查資料格式、分值、來源及引文，真實性仍須教師打開原卷覆核後確認。舊原創題只保留歷史。</p>${eligible().map(q=>`<article class="surface ac-managed"><h2>${h(title(q))}</h2>${sources(q)}<div class="button-row">${link('preview/'+q.id,'學生視角預覽')}${link('project/'+q.id,'課堂逐步講解')}</div><details><summary>編輯教練補充講解（不改原題與評分）</summary>${field('guide-'+q.id,'補充講解',a.guides[q.id]?.text||'','textarea','maxlength="6000"')}${btn('save-guide','保存講解',`data-id="${h(q.id)}"`)}</details></article>`).join('')}<h2>待核對真題</h2>${a.bank.questions.filter(q=>q.provenance.status!=='ready').map(q=>`<article class="surface"><h3>${h(q.year)} 第${q.number}題 · ${h(q.provenance.status)}</h3>${sources(q)}<details><summary>檢視原文、原題、評分及教練內容</summary>${q.passages.map(id=>{const p=a.bank.passages.find(p=>p.id===id);return `<h3>${h(p.title)}</h3>${p.paragraphs.map((t,i)=>`<p>${i+1}. ${h(t)}</p>`).join('')}`;}).join('')}${E.promptHTML(q)}${E.markingHTML(q,{}, {reveal:true})}</details><label class="choice"><input type="checkbox" data-confirm-source="${h(q.id)}"><span>我已對照原卷及評分文件，確認是正式DSE白話真題、原文及分值無誤。</span></label>${btn('verify-true-question','確認可供學生使用',`data-id="${h(q.id)}"`)}</article>`).join('')||'<p>沒有待核對資料。</p>'}<details class="surface"><summary>跨年配對及差異（教師）</summary>${A.pairings.map(p=>`<p><strong>${h(title(qby(p.from)))} → ${h(title(qby(p.to)))}</strong><br>${h(p.reason)}</p>`).join('')}</details>`);}
function classroom(){const a=state();shell(header('課堂派題與交卷','目前採離線檔案交換；下載檔案後交給對方，不會自動上傳。')+`<p class="note neutral">學生代號、教師名稱由檔案提供，身份未經驗證。支援限制是學習流程設定；作業檔內含題庫，不能當作保密考試機制。</p><div class="toolbar">${btn('import-packets','匯入作業／交卷／回饋包')}<input id="packet-files" type="file" accept=".json" multiple hidden>${link('records','完整個人備份','quiet')}</div><details class="surface"><summary>教師：建立作業包</summary>${field('assignment-title','作業名稱','','text','maxlength="160"')}<label class="field"><span>支援設定</span><select data-ac-field="support"><option value="after-first">保存首答後可自行開啟</option><option value="independent">這份作業只供自主作答</option></select></label>${eligible().map(q=>`<label class="choice"><input type="checkbox" data-assignment-q="${h(q.id)}"><span>${h(title(q))} · ${q.marks}分</span></label>`).join('')}${btn('create-assignment','建立並下載作業包','','primary')}</details><h2>作業</h2><div class="ac-grid">${Object.values(a.assignments).map(p=>`<article class="surface"><h3>${h(p.title)}</h3><p>${p.bank.questions.length}題 · 已收到${Object.values(a.submissions).filter(s=>s.assignmentId===p.id).length}份提交（包括重交）</p><div class="button-row">${link('assignment/'+p.id,'學生：進入作答')}${btn('download-assignment','下載作業包',`data-id="${h(p.id)}"`)}</div><details><summary>識別碼與題目固定版本</summary><p>${h(p.id)}</p>${Object.entries(p.versions).map(([id,v])=>`<p>${h(id)} · ${h(v)}</p>`).join('')}</details></article>`).join('')||'<p>先建立或匯入作業包。</p>'}</div><h2>提交與教師覆核</h2>${Object.values(a.submissions).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(s=>{const feedback=Object.values(a.feedback).filter(f=>f.submissionId===s.id);return `<article class="surface"><h3>${h(a.assignments[s.assignmentId]?.title)} · ${h(s.studentCode)}</h3><p>${h(s.createdAt)} · ${feedback.length?'已覆核／回饋可下載':'待教師覆核'}</p>${link('review/'+s.id,'教師：逐句診斷')}${feedback.map(f=>btn('download-feedback','下載回饋包',`data-id="${h(f.id)}"`)).join('')}</article>`;}).join('')||'<p>尚未有提交。只知道收到的交卷，沒有班級名單時不推定「未交」人數。</p>'}<p class="field-help">未配置資料庫、登入服務或模型金鑰：本版沒有雲端同步或AI自動診斷。教師逐句回饋可直接使用。</p>`);}
function working(a,id,code){a.working||={};const key=id+'|'+code;return a.working[key]||={};}
function assignmentPage(id){const a=state(),p=a.assignments[id];if(!p)return classroom();const code=a.activeCodes?.[id]||'';if(!code){shell(header(p.title,'先填學號或代號。不同代號的作答分開保存。')+field('student-code','學生代號','','text','maxlength="80"')+btn('set-student','進入作業',`data-id="${h(id)}"`,'primary'));return;}const work=working(a,id,code),subs=Object.values(a.submissions).filter(s=>s.assignmentId===id&&s.studentCode===code),feedback=Object.values(a.feedback).filter(f=>subs.some(s=>s.id===f.submissionId));shell(header(p.title,'學生代號：'+code+' · 本機保存 · '+(p.support==='independent'?'本作業自主作答':'保存首答後可開啟支援'))+`<div class="toolbar">${link('classroom','← 課堂')}${btn('change-student','切換學生代號',`data-id="${h(id)}"`)}</div>${p.bank.questions.map(q=>{const d=work[q.id]||C.newDraft(q);const comp=C.compile(p.bank);return `<section class="surface ac-assignment" data-work-q="${h(q.id)}">${E.promptHTML(q)}<details><summary>閱讀完整篇章及選取證據</summary>${comp.passages.filter(p=>q.passages.includes(p.id)).map(p=>`<h2>${h(p.title)}</h2>${p.paragraphs.map(par=>`<div class="paragraph"><span>${par.number}</span>${par.sentences.map(s=>`<label class="choice"><input type="checkbox" data-work-evidence="${h(s.id)}" ${d.evidence.includes(s.id)?'checked':''}><span>${h(s.text)}</span></label>`).join('')}</div>`).join('')}`).join('')}</details>${q.answerParts.map(f=>f.kind==='choice'?`<label class="field"><span>${h(f.label)} · ${f.marks}分</span><select data-work-answer="${h(f.key)}"><option value="">請選擇</option>${f.choices.map(c=>`<option value="${h(c.value)}" ${d.fields[f.key]===c.value?'selected':''}>${h(c.value+'. '+c.text)}</option>`).join('')}</select></label>`:`<label class="field"><span>${h(f.label)} · ${f.marks}分</span><textarea data-work-answer="${h(f.key)}" maxlength="12000">${h(d.fields[f.key]||'')}</textarea></label>`).join('')}<div class="button-row">${btn('work-first',d.firstAttempt?'保存修訂版本':'保存首答',`data-id="${h(q.id)}"`,'primary')}${p.support!=='independent'?btn('work-support','開啟本題支援',`data-id="${h(q.id)}" ${d.firstAttempt?'':'disabled'}`):''}</div><p class="save-label">本機草稿自動保存；${d.firstAttempt?'首答已另存':'尚未保存首答'}</p>${d.firstAttempt?`<details><summary>首答與修訂紀錄</summary><p class="answer-text">${h(C.assembleAnswer(d.firstAttempt,q.answerParts))}</p><p>首答支援紀錄：${h(d.firstAttempt.supportLog.map(x=>x.kind).join('、')||'無')}</p>${d.revisions.map((r,i)=>`<p>修訂${i+1}：${h(C.assembleAnswer(r,q.answerParts))}</p>`).join('')}</details>`:''}${d.examReviewed?`<p class="note neutral">教練提示：${h(q.hints.join('　'))}</p>${E.markingHTML(q,d,{reveal:true})}`:''}</section>`;}).join('')}<section class="surface"><h2>交卷／重交</h2><p>只匯出這份作業的答案、證據及支援歷程。下載後交給教師；不會傳送全部個人記錄。</p>${btn('submit-work','保存並下載交卷包',`data-id="${h(id)}"`,'primary')}${subs.map(s=>`<p>${h(s.createdAt)} ${btn('download-submission','再次下載',`data-id="${h(s.id)}"`)}</p>`).join('')}</section><h2>收到的回饋</h2>${feedback.map(f=>`<section class="surface"><h3>${h(f.reviewer)} · ${h(f.createdAt)}</h3><p>適用於提交 ${h(f.submissionId)}；重寫後保留這份舊版回饋。</p>${f.reviews.map(r=>{const d=work[r.qid],q=p.bank.questions.find(q=>q.id===r.qid),sub=a.submissions[f.submissionId],t=sub.attempts.find(x=>x.qid===q.id);return `<h3>第${q.number}題 · ${d&&C.assembleAnswer(d,q.answerParts)===t.answer?'目前答案版本':'舊答案版本，重寫後待再覆核'}</h3><p>已有內容：${h(r.observation)}</p><p>下一步：${h(r.next)}</p>${r.annotations.map(n=>`<blockquote>${h(n.quote)}<p>${h(n.note)}</p></blockquote>`).join('')}<p>教師評分：${r.score===null?'未評分':r.score+' / '+q.marks}</p>`;}).join('')}</section>`).join('')||'<p>尚未匯入回饋包。</p>'}`);}
function reviewPage(id){const a=state(),sub=a.submissions[id];if(!sub)return classroom();const p=a.assignments[sub.assignmentId];shell(header('逐句診斷與教師覆核',p.title+' · 學生代號 '+sub.studentCode)+`<p class="note neutral">本機教師流程，身份未驗證。引句須可在學生答案及原文中定位；可只寫追問，不提供完整改寫。</p>${field('reviewer','評閱人代號','','text','maxlength="80"')}<label class="choice"><input data-ac-field="questions-only" type="checkbox"><span>只給修訂追問，不提供完整改寫</span></label>${sub.attempts.map(item=>{const q=p.bank.questions.find(q=>q.id===item.qid);return `<section class="surface ac-review" data-review-q="${h(q.id)}"><h2>第${q.number}題 · ${q.marks}分</h2><p>${h(q.prompt)}</p><div class="attempt-comparison"><article><h3>首答</h3><p class="answer-text">${h(item.firstAttempt?C.assembleAnswer(item.firstAttempt,q.answerParts):'舊記錄沒有首答')}</p></article><article><h3>這次提交</h3><p class="answer-text">${h(item.answer)}</p></article></div><p class="field-help">支援：${h(item.supportLog.map(s=>s.kind).join('、')||'未記錄本題支援')} · 修訂${item.revisions.length}次</p>${E.markingHTML(q,{}, {reveal:true})}<label class="field"><span>選擇學生原句（可多加標註）</span><select data-note-sentence>${sentenceOptions(item.answer)}</select></label><label class="field"><span>連結原文段落與線索</span><select data-note-evidence>${p.bank.passages.filter(p=>q.passages.includes(p.id)).flatMap(p=>p.paragraphs.map((t,i)=>`<option value="${h(p.id+'|'+(i+1))}">第${i+1}段 · ${h(t.slice(0,80))}</option>`)).join('')}</select></label><label class="field"><span>已有內容／待釐清之處與一個修訂動作或追問</span><textarea data-note-text maxlength="3000"></textarea></label>${btn('add-note','加入這則標註',`data-id="${h(q.id)}"`)}<div id="notes-${h(q.id)}"></div><label class="field"><span>覆核結果</span><select data-review-result><option value="">請選擇</option><option value="confirmed">已回應</option><option value="revise">需要補充</option><option value="discuss">待釐清</option></select></label><label class="field"><span>已有內容（相較首答，哪些缺口已處理？）</span><textarea data-review-observation maxlength="3000"></textarea></label><label class="field"><span>下一步修訂動作／追問</span><textarea data-review-next maxlength="3000"></textarea></label><fieldset><legend>本次有證據支持的能力（須教師確認）</legend>${q.taskPlan.required.map(s=>`<label class="choice"><input type="checkbox" data-review-skill="${h(s)}"><span>${h(C.TASK_PRINCIPLES.find(x=>x.id===s).text)}</span></label>`).join('')}</fieldset><label class="field"><span>教師整體評分（選填；按原評分標準，非自檢欄加總）</span><input type="number" data-review-score min="0" max="${q.marks}" step="1"></label></section>`;}).join('')}${btn('save-feedback','確認覆核並下載回饋包',`data-id="${h(id)}"`,'primary')}`);restoreReviewDraft(id);}
function renderNotes(qid){document.getElementById('notes-'+qid).innerHTML=(reviewDrafts[qid]||[]).map((n,i)=>`<blockquote>${h(n.quote)}<p>${h(n.note)}</p>${btn('remove-note','移除',`data-id="${h(qid)}" data-index="${i}"`,'quiet')}</blockquote>`).join('');}
function persistReviewDraft(){if(!location.hash.startsWith('#review/'))return;const id=location.hash.slice(8);const values=[...main.querySelectorAll('input,textarea,select')].map(e=>({value:e.value,checked:e.checked}));state().reviewDrafts||={};state().reviewDrafts[id]={values,annotations:A.clone(reviewDrafts)};commit();}
function restoreReviewDraft(id){const d=state().reviewDrafts?.[id];reviewDrafts=A.clone(d?.annotations||{});if(d)[...main.querySelectorAll('input,textarea,select')].forEach((e,i)=>{if(d.values[i]){e.value=d.values[i].value;e.checked=d.values[i].checked;}});Object.keys(reviewDrafts).forEach(renderNotes);}
function preview(id){const q=qby(id);if(!q)return teacher();shell(header('學生視角預覽','教師預覽不改作答及支援記錄。')+link('teacher','返回真題管理')+'<div class="ac-two"><section class="surface">'+passage(q)+'</section><section class="surface">'+E.promptHTML(q)+E.answerHTML(q,C.newDraft(q))+'<details><summary>檢視來源評分及教練分析</summary>'+E.markingHTML(q,{}, {reveal:true})+E.evidenceHTML(q,{examReviewed:true,evidence:[]})+'</details></section></div>');}
function sentenceOptions(answer){let pos=0;return (answer.match(/[^。！？\n]+[。！？]?|\n/g)||[]).flatMap(t=>{const start=pos;pos+=t.length;if(!t.trim())return [];return `<option value="${start}|${pos}">${h(t)}</option>`;}).join('');}
function route(path,adapter){api=adapter;main=adapter.main;activeRepair=null;if(path==='home'){home();return true;}if(path==='repairs'){repairList();return true;}if(path.startsWith('repair/')){repair(path.slice(7));return true;}if(path==='challenge'){challenge();return true;}if(path==='abilities'){abilities();return true;}if(path==='teacher'){teacher();return true;}if(path==='classroom'){classroom();return true;}if(path.startsWith('project/')){project(path.slice(8));return true;}if(path.startsWith('assignment/')){assignmentPage(path.slice(11));return true;}if(path.startsWith('preview/')){preview(path.slice(8));return true;}if(path.startsWith('review/')){reviewPage(path.slice(7));return true;}return false;}
function currentWork(){const a=state(),id=location.hash.slice('#assignment/'.length),p=a.assignments[id],code=a.activeCodes?.[id];return {a,id,p,code,work:p&&code?working(a,id,code):null};}
async function click(event){const source=event.target.closest('[data-source-exposure]');if(source&&api&&!location.hash.startsWith('#teacher')&&!location.hash.startsWith('#preview/')&&!location.hash.startsWith('#project/'))api.noteExposure(source.dataset.sourceExposure,'source');const b=event.target.closest('[data-academy]');if(!b||b.disabled||!api)return;const action=b.dataset.academy,id=b.dataset.id;try{const a=state();
if(action==='repair-evidence'){const d=a.repairs[activeRepair];d.evidence=d.evidence.includes(id)?d.evidence.filter(x=>x!==id):[...d.evidence,id];b.classList.toggle('selected',d.evidence.includes(id));b.setAttribute('aria-pressed',d.evidence.includes(id));document.getElementById('repair-selected').textContent='已選 '+d.evidence.length+'句證據';commit();}
else if(action==='save-repair'){A.saveRepair(a,activeRepair,a.repairs[activeRepair]);commit();repair(activeRepair);status('診斷及重寫已保存。你可先再修訂，或主動查看指引。');}
else if(action==='reveal-repair'){const d=a.repairs[activeRepair];if(!d?.savedAt)throw Error('請先保存診斷及重寫。');d.revealedAt||=A.now();commit();repair(activeRepair);}
else if(action==='save-days'){const days=[Number(value('day1')),Number(value('day2'))];if(days.some(x=>!Number.isInteger(x)||x<1||x>365))throw Error('請填1至365天。');a.reviewDays=days;commit();abilities();}
else if(action==='project-prev'||action==='project-next'){projectStep+=action.endsWith('next')?1:-1;project(projectQ);}
else if(action==='save-guide'){a.guides[id]={text:value('guide-'+id),at:A.now(),questionVersion:A.version(qby(id),data().passages)};commit();status('補充講解已保存，學生開啟支援後可閱讀。');}
else if(action==='export-true-bank'){api.download('readingcoach-verified-dse.json',JSON.stringify(A.selectBank(eligible().map(q=>q.id),data().questions,data().passages),null,2));}
else if(action==='import-true-bank'){document.getElementById('true-bank-file').click();}
else if(action==='verify-true-question'){if(!main.querySelector(`[data-confirm-source="${id}"]`)?.checked)throw Error('請先對照來源並勾選確認。');const q=a.bank.questions.find(q=>q.id===id);q.provenance.status='ready';q.provenance.checkedAt=A.hkDate(A.now());q.passages.forEach(id=>a.bank.passages.find(p=>p.id===id).verified=true);api.rebuild();commit();teacher();}
else if(action==='import-packets'){document.getElementById('packet-files').click();}
else if(action==='create-assignment'){const ids=[...main.querySelectorAll('[data-assignment-q]:checked')].map(e=>e.dataset.assignmentQ);const p=A.assignment(ids,data().questions,data().passages,value('assignment-title'),value('support'));A.addUnique(a.assignments,p);commit();api.download('assignment-'+p.id+'.json',JSON.stringify(p,null,2));classroom();status('已下載作業包。請交給學生匯入；沒有上傳。');}
else if(action==='download-assignment'||action==='download-submission'||action==='download-feedback'){const map=action.endsWith('assignment')?'assignments':action.endsWith('submission')?'submissions':'feedback';api.download(id+'.json',JSON.stringify(a[map][id],null,2));}
else if(action==='set-student'){const code=value('student-code').trim();if(!code)throw Error('請填學生代號。');a.activeCodes||={};a.activeCodes[id]=code;commit();assignmentPage(id);}
else if(action==='change-student'){delete a.activeCodes[id];commit();assignmentPage(id);}
else if(action==='work-first'||action==='work-support'){const {p,work}=currentWork(),q=p.bank.questions.find(q=>q.id===id),d=work[id]||C.newDraft(q);if(!C.answerComplete(q,d,q.answerParts))throw Error('請先填妥本題全部分題。');if(action==='work-first'){C.captureFirstAttempt(q,d,q.answerParts);C.saveRevision(q,d,q.answerParts,'classroom');}else{if(p.support==='independent'||!d.firstAttempt)throw Error('本作業未開放支援。');C.recordSupport(q,d,q.answerParts,'source');d.examReviewed=true;}work[id]=d;commit();assignmentPage(p.id);}
else if(action==='submit-work'){const {p,work,code}=currentWork();const attempts=p.bank.questions.map(q=>{const d=work[q.id];if(!d||!C.answerComplete(q,d,q.answerParts))throw Error('請完成全部題目及分題。');C.captureFirstAttempt(q,d,q.answerParts);C.saveRevision(q,d,q.answerParts,'submission');return A.snapshot(q,d,p.bank.passages);});const sub=A.submission(p,code,attempts);A.validateSubmission(sub,p);A.addUnique(a.submissions,sub);commit();api.download(sub.id+'.json',JSON.stringify(sub,null,2));assignmentPage(p.id);status('已保存並下載交卷包；請交給教師。');}
else if(action==='add-note'){const sid=location.hash.slice('#review/'.length),sub=a.submissions[sid],p=a.assignments[sub.assignmentId],item=sub.attempts.find(x=>x.qid===id),section=main.querySelector(`[data-review-q="${id}"]`);const [start,end]=section.querySelector('[data-note-sentence]').value.split('|').map(Number),[pid,pn]=section.querySelector('[data-note-evidence]').value.split('|'),note=section.querySelector('[data-note-text]').value.trim();if(!note)throw Error('請填具體意見或追問。');reviewDrafts[id]||=[];reviewDrafts[id].push({start,end,quote:item.answer.slice(start,end),passageId:pid,paragraph:Number(pn),evidence:p.bank.passages.find(x=>x.id===pid).paragraphs[Number(pn)-1],note});renderNotes(id);section.querySelector('[data-note-text]').value='';persistReviewDraft();}
else if(action==='remove-note'){reviewDrafts[id].splice(Number(b.dataset.index),1);renderNotes(id);persistReviewDraft();}
else if(action==='save-feedback'){const sub=a.submissions[id],p=a.assignments[sub.assignmentId];const reviews=sub.attempts.map(item=>{const s=main.querySelector(`[data-review-q="${item.qid}"]`),score=s.querySelector('[data-review-score]').value;return {qid:item.qid,answerFingerprint:A.fingerprint(item),result:s.querySelector('[data-review-result]').value,observation:s.querySelector('[data-review-observation]').value,next:s.querySelector('[data-review-next]').value,annotations:reviewDrafts[item.qid]||[],score:score===''?null:Number(score),skills:[...s.querySelectorAll('[data-review-skill]:checked')].map(e=>e.dataset.reviewSkill),questionsOnly:main.querySelector('[data-ac-field="questions-only"]').checked};});const f=A.feedback(sub,p,value('reviewer'),reviews);A.addUnique(a.feedback,f);commit();api.download(f.id+'.json',JSON.stringify(f,null,2));classroom();status('已保存這份提交版本的回饋，並下載回饋包。');}
}catch(e){status(e.message,true);}}
function input(event){if(!api)return;const el=event.target,a=state();if(location.hash.startsWith('#review/')){persistReviewDraft();return;}if(activeRepair&&['diagnosis','rewrite'].includes(el.dataset.acField)){a.repairs[activeRepair][el.dataset.acField]=el.value;commit();return;}if(el.dataset.workAnswer!==undefined){const {p,work}=currentWork(),qid=el.closest('[data-work-q]').dataset.workQ,q=p.bank.questions.find(q=>q.id===qid);const d=work[qid]||=C.newDraft(q);inheritExposure(q,d);d.fields[el.dataset.workAnswer]=el.value;d.updatedAt=A.now();commit();}}
function inheritExposure(q,d){const a=state(),local=get().drafts[q.id];if(!d.firstAttempt&&!d.supportLog.length){d.supportLog=A.clone(local?.supportLog||[]);if(a.declarations[q.id]||local?.firstAttempt)d.supportLog.push({kind:'legacy',at:A.now()});}}
async function change(event){if(!api)return;const el=event.target;try{let a=state();if(location.hash.startsWith('#review/')){persistReviewDraft();return;}if(el.dataset.acField==='ability-code'){a.abilityStudentCode=el.value;commit();abilities();return;}if(el.dataset.acDeclare){a.declarations[el.dataset.acDeclare]=el.checked;commit();return;}if(el.dataset.workEvidence){const {p,work}=currentWork(),qid=el.closest('[data-work-q]').dataset.workQ,q=p.bank.questions.find(q=>q.id===qid),d=work[qid]||=C.newDraft(q);d.evidence=el.checked?[...new Set([...d.evidence,el.dataset.workEvidence])]:d.evidence.filter(x=>x!==el.dataset.workEvidence);commit();return;}if(el.id==='true-bank-file'){const file=el.files[0];if(!file)return;if(file.size>4*1024*1024)throw Error('真題包須小於4 MB。');const bank=JSON.parse(await file.text()),errors=A.validateBank(bank);if(errors.length)throw Error(errors.slice(0,6).join('；'));for(const q of bank.questions){const existing=qby(q.id);if(existing&&A.version(existing,data().passages)!==A.version(q,bank.passages))throw Error(q.id+'已有不同版本；請另用版本識別碼，舊答案不會被覆寫。');}const existing=data();const ps=bank.passages.filter(p=>!existing.passages.some(x=>x.id===p.id));for(const p of bank.passages){const old=existing.passages.find(x=>x.id===p.id);if(old&&A.fingerprint(old)!==A.fingerprint(p))throw Error(p.id+'已有不同原文版本。');}const qs=bank.questions.filter(q=>!existing.questions.some(x=>x.id===q.id)).map(q=>({...q,provenance:{...q.provenance,status:'checking'}}));a.bank.passages.push(...ps);a.bank.questions.push(...qs);api.rebuild();commit();teacher();status('已匯入'+qs.length+'道待核對真題；相同版本已略過。');return;}
if(el.id==='packet-files'){let added=0,duplicates=0;const packets=[];for(const file of el.files){if(file.size>8*1024*1024)throw Error(file.name+'超過8 MB。');packets.push(JSON.parse(await file.text()));}packets.sort((x,y)=>['assignment','submission','feedback'].indexOf(x.kind)-['assignment','submission','feedback'].indexOf(y.kind));for(const p of packets){if(p.kind==='assignment'){A.validateAssignment(p);for(const q of p.bank.questions){const old=qby(q.id);if(old&&A.version(old,data().passages)!==p.versions[q.id])throw Error(q.id+'與本機題目版本不符，請教師重新匯出一致版本。');}A.addUnique(a.assignments,p)?added++:duplicates++;}else if(p.kind==='submission'){const assignment=a.assignments[p.assignmentId];if(!assignment)throw Error('請先匯入相應作業包。');A.validateSubmission(p,assignment);A.addUnique(a.submissions,p)?added++:duplicates++;const work=working(a,p.assignmentId,p.studentCode),comp=C.compile(assignment.bank);for(const t of p.attempts)if(!work[t.qid]){const q=comp.questions.find(q=>q.id===t.qid);work[t.qid]=C.sanitizeDraft({...t,mode:'guided',practiceMode:t.firstAttempt?.practiceMode||'independent'},q,q.answerParts,comp.sentences);}}else if(p.kind==='feedback'){const sub=a.submissions[p.submissionId],assignment=a.assignments[p.assignmentId];if(!sub||!assignment)throw Error('找不到相應作業及提交；請在原作答瀏覽器匯入，或先匯入作業及自己的交卷包。');A.validateFeedback(p,sub,assignment);A.addUnique(a.feedback,p)?added++:duplicates++;}else throw Error('不是作業／交卷／回饋包。');commit();}classroom();status('已匯入'+added+'個檔案；略過'+duplicates+'個重複版本。');}}
catch(e){status(e instanceof SyntaxError?'不是有效JSON；現有資料仍保留。':e.message,true);}finally{if(el.type==='file')el.value='';}}
root.document?.addEventListener('click',click);root.document?.addEventListener('input',input);root.document?.addEventListener('change',change);root.document?.addEventListener('keydown',e=>{if(location.hash.startsWith('#project/')&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();projectStep+=e.key==='ArrowRight'?1:-1;project(projectQ);}});
root.CoachAcademyUI={route,home,transfer};
})(window);
